export async function recordChange(entity, id, before, after, userId) {
  const diff = {};
  for (const k of new Set([...Object.keys(before), ...Object.keys(after)])) {
    if (before[k] !== after[k]) diff[k] = { from: before[k], to: after[k] };
  }
  if (!Object.keys(diff).length) return;
  await db('audit_log').insert({ entity: '{{entity}}', entity_id: id, diff, user_id: userId, ts: new Date() });
}
